#include "KernelStore.h"
#include "PtxCrypt.h"
#include "Obfuscate.h"
#include <cuda.h>
#include <stdexcept>
#include <string>

// Auto-generated by the build: encrypt_ptx tool produces these headers.
// Each header defines: static const uint8_t NAME[] = { ... };
//                       static const size_t NAME_size = ...;
#include "genesis_enc.h"
#include "http_enc.h"
#include "io_enc.h"

namespace symm::protect {

static KernelHandles g_kernels{};

// Decrypt one encrypted PTX blob and load it into a CUDA module.
// The plaintext PTX is securely zeroed as soon as cuModuleLoadData returns.
static CUmodule loadBlob(const uint8_t* blob, size_t blobSize) {
    std::string ptx = PtxCrypt::decrypt(blob, blobSize);

    CUmodule mod = nullptr;
    CUresult r = cuModuleLoadData(&mod, ptx.c_str());

    // Zero before checking result — we never want plaintext to linger
    PtxCrypt::secureZero(ptx.data(), ptx.size());

    if (r != CUDA_SUCCESS) {
        const char* msg = nullptr;
        cuGetErrorString(r, &msg);
        throw std::runtime_error(
            std::string(SYMM_STR("KernelStore: ")) + (msg ? msg : "load failed"));
    }
    return mod;
}

KernelHandles loadKernels() {
    // Ensure driver API context is active — safe to call redundantly
    cuInit(0);
    CUdevice dev = 0;
    CUcontext ctx = nullptr;
    cuDeviceGet(&dev, 0);
    cuDevicePrimaryCtxRetain(&ctx, dev);
    cuCtxSetCurrent(ctx);

    KernelHandles h{};

    h.genesis_mod = loadBlob(SYMM_GENESIS_PTX, SYMM_GENESIS_PTX_size);
    CUresult r = cuModuleGetFunction(&h.symm_core, h.genesis_mod,
                                     SYMM_STR("symm_core"));
    if (r != CUDA_SUCCESS)
        throw std::runtime_error(SYMM_STR("KernelStore: symm_core not found"));

    h.http_mod = loadBlob(SYMM_HTTP_PTX, SYMM_HTTP_PTX_size);
    h.io_mod   = loadBlob(SYMM_IO_PTX,   SYMM_IO_PTX_size);

    g_kernels = h;
    return h;
}

const KernelHandles& kernels() { return g_kernels; }

} // namespace symm::protect
